import java.io.*;
import java.util.*;

public class Main {
    // Fenwick Tree / Binary Indexed Tree
    static class Fenwick {
        long[] bit;
        int n;

        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }

        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += val;
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }
    }

    // Range add / range sum using two Fenwick trees
    static class RangeFenwick {
        int n;
        Fenwick b1, b2;

        RangeFenwick(int n) {
            this.n = n;
            b1 = new Fenwick(n);
            b2 = new Fenwick(n);
        }

        void internalAdd(Fenwick b, int idx, long val) {
            if (idx <= n) b.add(idx, val);
        }

        void rangeAdd(int l, int r, long x) {
            internalAdd(b1, l, x);
            internalAdd(b1, r + 1, -x);
            internalAdd(b2, l, x * (l - 1));
            internalAdd(b2, r + 1, -x * r);
        }

        long prefixSum(int p) {
            return b1.sum(p) * p - b2.sum(p);
        }

        long rangeSum(int l, int r) {
            return prefixSum(r) - prefixSum(l - 1);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        int q = fs.nextInt();

        RangeFenwick rf = new RangeFenwick(n);
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String op = fs.next();
            if (op == null) break;

            // Support common formats:
            // 0 s t x / 1 s t
            // add s t x / getSum s t
            if (op.equals("0") || op.equalsIgnoreCase("add")) {
                int s = fs.nextInt();
                int t = fs.nextInt();
                long x = fs.nextLong();
                rf.rangeAdd(s, t, x);
            } else {
                int s = fs.nextInt();
                int t = fs.nextInt();
                out.append(rf.rangeSum(s, t)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

import sys

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit1 = [0] * (n + 2)
        self.bit2 = [0] * (n + 2)

    def _add(self, bit, idx, val):
        while idx <= self.n:
            bit[idx] += val
            idx += idx & -idx

    def _sum(self, bit, idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    def range_add(self, l, r, val):
        self._add(self.bit1, l, val)
        self._add(self.bit1, r + 1, -val)
        self._add(self.bit2, l, val * (l - 1))
        self._add(self.bit2, r + 1, -val * r)

    def prefix_sum(self, idx):
        return self._sum(self.bit1, idx) * idx - self._sum(self.bit2, idx)

    def range_sum(self, l, r):
        return self.prefix_sum(r) - self.prefix_sum(l - 1)


