import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s


def range_add(bit1, bit2, l, r, x, n):
    bit1.add(l, x)
    if r + 1 <= n:
        bit1.add(r + 1, -x)
    bit2.add(l, x * (l - 1))
    if r + 1 <= n:
        bit2.add(r + 1, -x * r)


def prefix_sum(bit1, bit2, i):
    return bit1.sum(i) * i - bit2.sum(i)


def range_sum(bit1, bit2, l, r):
    return prefix_sum(bit1, bit2, r) - prefix_sum(bit1, bit2, l - 1)


def main():
    input = sys.stdin.readline
    n, q = map(int, input().split())

    bit1 = Fenwick(n)
    bit2 = Fenwick(n)

    out = []
    for _ in range(q):
        query = input().split()
        if query[0] == '0':
            _, s, t, x = query
            s = int(s)
            t = int(t)
            x = int(x)
            range_add(bit1, bit2, s, t, x, n)
        else:
            _, s, t = query
            s = int(s)
            t = int(t)
            out.append(str(range_sum(bit1, bit2, s, t)))

    sys.stdout.write("\n".join(out))


